package com.dannyboi.karaokeremote;
import android.app.*;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.media.*;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.net.wifi.WifiManager;import android.view.*;import android.widget.*;
import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class MainActivity extends Activity {
 EditText host,pin,search; LinearLayout results,queue; TextView status; Button connectButton,findButton,refreshButton,micButton; LinearLayout connectedArea,hostsFound; boolean connected=false; Handler handler=new Handler(); volatile boolean micOn=false; Thread micThread; int bg=0xff0d1023, panel=0xff1d2040, pink=0xffff1493;
 void text(String s){runOnUiThread(()->status.setText(s));} TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(size);t.setPadding(10,12,10,12);return t;}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(-1);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(pink));return b;}
 EditText edit(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setHintTextColor(0xffaaaaaa);e.setTextColor(-1);return e;}
 void line(LinearLayout root,View v){root.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(bg);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,20,18,30);scroll.addView(root);setContentView(scroll);
 TextView title=label("🎤 dannyboi's Karaoke",27);title.setTypeface(null,Typeface.BOLD);title.setTextColor(0xffff63e2);line(root,title);line(root,label("PHONE REMOTE · SEARCH · QUEUE · MIC",12));
 host=edit("Windows PC IP or IP:port (example: 192.168.1.5:8877)");pin=edit("6-digit pairing PIN");android.content.SharedPreferences prefs=getSharedPreferences("remote",0);host.setText(prefs.getString("host",""));pin.setText(prefs.getString("pin",""));line(root,host);line(root,pin);
 Button scan=button("Scan Wi-Fi for Karaoke Host");line(root,scan);hostsFound=new LinearLayout(this);hostsFound.setOrientation(1);line(root,hostsFound);scan.setOnClickListener(v->scanHosts());
 connectButton=button("Connect to Windows Karaoke");line(root,connectButton);connectButton.setOnClickListener(v->{prefs.edit().putString("host",host.getText().toString().trim()).putString("pin",pin.getText().toString().trim()).apply();text("Connecting...");request("GET","/remote/queue",null,data->{connected=true;connectedArea.setVisibility(View.VISIBLE);connectButton.setText("Connected ✓ — Disconnect");text("Connected to Windows karaoke");refreshQueue();});});
 connectedArea=new LinearLayout(this);connectedArea.setOrientation(1);connectedArea.setVisibility(View.GONE);line(root,connectedArea);search=edit("Search YouTube karaoke songs");line(connectedArea,search);findButton=button("Search Songs");Button find=findButton;line(connectedArea,find);results=new LinearLayout(this);results.setOrientation(1);line(connectedArea,results);find.setOnClickListener(v->{String query=search.getText().toString().trim();if(query.isEmpty()){text("Enter a song or artist to search");return;}text("Searching YouTube karaoke...");request("GET","/remote/search?q="+Uri(query),null,data->{results.removeAllViews();JSONArray songs=data.optJSONArray("results");if(songs==null||songs.length()==0){text("No matching karaoke songs found");line(results,label("No songs found. Try another title.",14));return;}text("Found "+songs.length()+" results");for(int i=0;i<songs.length();i++){JSONObject item=songs.optJSONObject(i);if(item==null)continue;String id=item.optString("videoId"),name=item.optString("title"),artist=item.optString("channel");if(!id.matches("[A-Za-z0-9_-]{11}"))continue;LinearLayout itemRow=new LinearLayout(this);itemRow.setOrientation(0);itemRow.setGravity(Gravity.CENTER_VERTICAL);line(results,itemRow);ImageView preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.CENTER_CROP);LinearLayout.LayoutParams imageParams=new LinearLayout.LayoutParams(132,86);imageParams.setMargins(0,6,12,6);itemRow.addView(preview,imageParams);loadThumbnail(preview,id);TextView titleRow=label(android.text.Html.fromHtml(name,android.text.Html.FROM_HTML_MODE_LEGACY)+"\n"+artist,14);itemRow.addView(titleRow,new LinearLayout.LayoutParams(0,-2,1));Button add=button("Add to Queue");line(results,add);add.setOnClickListener(w->{JSONObject obj=new JSONObject();try{obj.put("videoId",id);obj.put("title",name);obj.put("artist",artist);}catch(Exception ignored){}request("POST","/remote/queue",obj,d->{text("Added: "+name);refreshQueue();});});}});});
 line(connectedArea,label("♫ Singing Queue",20));Button refresh=button("Refresh Queue");line(connectedArea,refresh);queue=new LinearLayout(this);queue.setOrientation(1);line(connectedArea,queue);refresh.setOnClickListener(v->refreshQueue());
 Button mic=button("🎤 Start Phone Microphone");line(connectedArea,mic);line(connectedArea,label("Mic streams to your PC over Wi-Fi. Run the included mic receiver on Windows. Use headphones to avoid feedback.",12));mic.setOnClickListener(v->{if(micOn){micOn=false;mic.setText("🎤 Start Phone Microphone");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},10);return;}micOn=true;mic.setText("■ Stop Microphone");startMic();});status=label("Enter your Windows PC IP and pairing PIN.",13);line(root,status);
 }
 static String Uri(String v){try{return java.net.URLEncoder.encode(v,"UTF-8");}catch(Exception e){return v;}}
 interface Done{void go(JSONObject data);}
 void request(String method,String path,JSONObject body,Done done){String ip=host.getText().toString().trim(),code=pin.getText().toString().trim();if(!code.matches("\\d{6}")){text("Enter the 6-digit pairing PIN");return;}if(ip.startsWith("http://"))ip=ip.substring(7);if(ip.startsWith("https://")){text("Use a local http:// address");return;}if(ip.endsWith("/"))ip=ip.substring(0,ip.length()-1);if(!ip.matches("(?:\\d{1,3}\\.){3}\\d{1,3}(?::\\d{2,5})?")){text("Enter PC IP, optionally with :8877");return;}final String address=ip.contains(":")?ip:ip+":8877";new Thread(()->{try{URL u=new URL("http://"+address+path);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod(method);c.setConnectTimeout(6000);c.setReadTimeout(15000);c.setRequestProperty("X-Remote-PIN",code);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.getOutputStream().write(body.toString().getBytes(StandardCharsets.UTF_8));}int rc=c.getResponseCode();InputStream in=rc<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);JSONObject data=new JSONObject(out.toString("UTF-8"));if(rc>=400)throw new Exception(data.optString("error","HTTP "+rc));runOnUiThread(()->done.go(data));}catch(Exception e){text("Connection error: "+e.getMessage());}}).start();}
 void loadThumbnail(ImageView target,String videoId){new Thread(()->{try{URL url=new URL("https://img.youtube.com/vi/"+videoId+"/mqdefault.jpg");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);Bitmap bmp=BitmapFactory.decodeStream(c.getInputStream());if(bmp!=null)runOnUiThread(()->target.setImageBitmap(bmp));c.disconnect();}catch(Exception ignored){}}).start();}
 void scanHosts(){hostsFound.removeAllViews();text("Scanning local Wi-Fi for karaoke hosts...");new Thread(()->{try{WifiManager wm=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);int raw=wm.getDhcpInfo().ipAddress;if(raw==0)raw=wm.getConnectionInfo().getIpAddress();if(raw==0){text("Connect to Wi-Fi before scanning");return;}String prefix=(raw&255)+"."+((raw>>8)&255)+"."+((raw>>16)&255)+".";java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(24);java.util.concurrent.atomic.AtomicInteger found=new java.util.concurrent.atomic.AtomicInteger();java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(254);for(int i=1;i<=254;i++){final String address=prefix+i;pool.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL("http://"+address+":8877/remote/health").openConnection();c.setConnectTimeout(450);c.setReadTimeout(450);if(c.getResponseCode()==200){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[256];int n;try(InputStream in=c.getInputStream()){while((n=in.read(buf))>0&&out.size()<1024)out.write(buf,0,n);}if(new JSONObject(out.toString("UTF-8")).optBoolean("remote")){found.incrementAndGet();runOnUiThread(()->{Button pick=button("Use Karaoke Host: "+address);line(hostsFound,pick);pick.setOnClickListener(v->{host.setText(address+":8877");text("Host selected. Enter current PIN and connect.");});});}}c.disconnect();}catch(Exception ignored){}finally{latch.countDown();}});}latch.await(20,java.util.concurrent.TimeUnit.SECONDS);pool.shutdownNow();text(found.get()==0?"No karaoke hosts found. Check Wi-Fi, firewall, and PC IP.":"Found "+found.get()+" karaoke host(s). Select one.");}catch(Exception e){text("Scan error: "+e.getMessage());}}).start();}
 void refreshQueue(){request("GET","/remote/queue",null,data->{queue.removeAllViews();JSONArray list=data.optJSONArray("queue");if(list==null||list.length()==0){line(queue,label("No songs queued",13));return;}for(int i=0;i<list.length();i++){JSONObject s=list.optJSONObject(i);if(s==null)continue;int id=s.optInt("id");line(queue,label((i+1)+". "+android.text.Html.fromHtml(s.optString("title"),android.text.Html.FROM_HTML_MODE_LEGACY),14));Button del=button("Remove");line(queue,del);del.setOnClickListener(v->request("DELETE","/remote/queue/"+id,null,d->refreshQueue()));}});}
 void startMic(){final String ip=host.getText().toString().trim().replace("http://", "").split(":")[0],code=pin.getText().toString().trim();micThread=new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_AUDIO);int rate=16000;int min=AudioRecord.getMinBufferSize(rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);AudioRecord rec=null;DatagramSocket sock=null;try{rec=new AudioRecord(MediaRecorder.AudioSource.MIC,rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min,4096));sock=new DatagramSocket();InetAddress addr=InetAddress.getByName(ip);byte[] data=new byte[640],packet=new byte[646];byte[] auth=code.getBytes(StandardCharsets.US_ASCII);System.arraycopy(auth,0,packet,0,6);rec.startRecording();while(micOn){int n=rec.read(data,0,data.length);if(n>0){System.arraycopy(data,0,packet,6,n);sock.send(new DatagramPacket(packet,n+6,addr,8878));}}}catch(Exception e){text("Mic error: "+e.getMessage());}finally{micOn=false;if(rec!=null){try{rec.stop();}catch(Exception ignored){}rec.release();}if(sock!=null)sock.close();}});micThread.start();}
 @Override protected void onDestroy(){micOn=false;super.onDestroy();}
}
